# PlatformIO pre-build script: create include/talkie_secret.h on first build.
#
# The stick and the receiver must be built from the same checkout so they get
# the same secret. It never leaves your machine; delete the file to rotate it
# (then reflash BOTH devices).
import os
import secrets

Import("env")  # noqa: F821  (provided by PlatformIO/SCons)

path = os.path.join(env.subst("$PROJECT_DIR"), "include", "talkie_secret.h")  # noqa: F821
if not os.path.exists(path):
    with open(path, "w") as f:
        f.write(
            "// Generated by scripts/gen_secret.py. Keep private. Both devices must be\n"
            "// flashed from builds that used this exact file.\n"
            "#pragma once\n"
            '#define TK_SECRET "%s"\n' % secrets.token_hex(32)
        )
    print("Claude Talkie: generated a new pairing secret in include/talkie_secret.h")
